package com.example.starter.evidence;

/**
 * 证物状态。
 * SEALED 已封存；TRANSFER_PENDING 待接收（交接进行中）；SEAL_BROKEN 封条异常（终态，不可恢复）。
 */
public enum EvidenceStatus {
    SEALED,
    TRANSFER_PENDING,
    SEAL_BROKEN
}

package com.example.starter.evidence;

/**
 * 交接记录状态。
 * PENDING 待接收；ACCEPTED 已接受；CANCELLED 已取消。决定后不可再变。
 */
public enum TransferStatus {
    PENDING,
    ACCEPTED,
    CANCELLED
}

