package com.example.starter.evidence;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

/**
 * 证物表访问。状态与保管人变更必须先通过 {@link #findByKeyForUpdate} 锁定证物行，
 * 保证并发交接/取消/核验按事务提交顺序生效。
 */
@Repository
public class EvidenceRepository {

    private static final EvidenceRowMapper ROW_MAPPER = new EvidenceRowMapper();

    private final JdbcTemplate jdbc;

    public EvidenceRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 插入新证物，初始状态 SEALED，保管人为入库操作人。
     */
    public void insert(String evidenceKey, String caseKey, String category, String sealNo,
                       String custodianId, LocalDateTime now) {
        jdbc.update("""
                        INSERT INTO evidence
                            (evidence_key, case_key, category, seal_no, custodian_id, status, created_at, updated_at)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                        """,
                evidenceKey, caseKey, category, sealNo, custodianId,
                EvidenceStatus.SEALED.name(), now, now);
    }

    /**
     * 按业务键查询（不加锁），用于只读场景。
     */
    public Optional<Evidence> findByKey(String evidenceKey) {
        List<Evidence> rows = jdbc.query(
                "SELECT * FROM evidence WHERE evidence_key = ?", ROW_MAPPER, evidenceKey);
        return rows.stream().findFirst();
    }

    /**
     * 按业务键查询并锁定证物行（SELECT ... FOR UPDATE），用于一切状态/保管人变更。
     */
    public Optional<Evidence> findByKeyForUpdate(String evidenceKey) {
        List<Evidence> rows = jdbc.query(
                "SELECT * FROM evidence WHERE evidence_key = ? FOR UPDATE", ROW_MAPPER, evidenceKey);
        return rows.stream().findFirst();
    }

    /**
     * 更新证物状态与保管人（交接接受时原子切换保管人）。
     */
    public void updateCustody(String evidenceKey, String custodianId, EvidenceStatus status,
                              LocalDateTime now) {
        jdbc.update(
                "UPDATE evidence SET custodian_id = ?, status = ?, updated_at = ? WHERE evidence_key = ?",
                custodianId, status.name(), now, evidenceKey);
    }

    /**
     * 仅更新证物状态（交接发起/取消、核验失败）。
     */
    public void updateStatus(String evidenceKey, EvidenceStatus status, LocalDateTime now) {
        jdbc.update(
                "UPDATE evidence SET status = ?, updated_at = ? WHERE evidence_key = ?",
                status.name(), now, evidenceKey);
    }

    /**
     * 查询指定保管人当前可交接的证物（本人保管且状态 SEALED）。
     */
    public List<Evidence> findTransferable(String custodianId) {
        return jdbc.query(
                "SELECT * FROM evidence WHERE custodian_id = ? AND status = ? ORDER BY id",
                ROW_MAPPER, custodianId, EvidenceStatus.SEALED.name());
    }

    private static final class EvidenceRowMapper implements RowMapper<Evidence> {
        @Override
        public Evidence mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new Evidence(
                    rs.getLong("id"),
                    rs.getString("evidence_key"),
                    rs.getString("case_key"),
                    rs.getString("category"),
                    rs.getString("seal_no"),
                    rs.getString("custodian_id"),
                    EvidenceStatus.valueOf(rs.getString("status")),
                    rs.getObject("created_at", LocalDateTime.class),
                    rs.getObject("updated_at", LocalDateTime.class));
        }
    }
}

package com.example.starter.evidence;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

/**
 * 交接记录表访问。记录只追加；进行中的交接通过证物行锁保证同一证物最多一条 PENDING。
 */
@Repository
public class TransferRecordRepository {

    private static final TransferRowMapper ROW_MAPPER = new TransferRowMapper();

    private final JdbcTemplate jdbc;

    public TransferRecordRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 追加一条待接收交接记录。
     */
    public void insert(String evidenceKey, String fromCustodian, String toCustodian,
                       LocalDateTime now) {
        jdbc.update("""
                        INSERT INTO transfer_record
                            (evidence_key, from_custodian, to_custodian, status, initiated_by, created_at, decided_at)
                        VALUES (?, ?, ?, ?, ?, ?, NULL)
                        """,
                evidenceKey, fromCustodian, toCustodian,
                TransferStatus.PENDING.name(), fromCustodian, now);
    }

    /**
     * 查询证物当前待接收的交接（调用前必须已锁定证物行）。
     */
    public Optional<TransferRecord> findPendingByEvidenceKey(String evidenceKey) {
        List<TransferRecord> rows = jdbc.query(
                "SELECT * FROM transfer_record WHERE evidence_key = ? AND status = ?",
                ROW_MAPPER, evidenceKey, TransferStatus.PENDING.name());
        return rows.stream().findFirst();
    }

    /**
     * 将待接收交接决定为 ACCEPTED 或 CANCELLED；仅当仍为 PENDING 时生效。
     *
     * @return 是否成功决定（false 表示已被并发事务先行决定）
     */
    public boolean decide(long id, TransferStatus decided, LocalDateTime decidedAt) {
        int updated = jdbc.update(
                "UPDATE transfer_record SET status = ?, decided_at = ? WHERE id = ? AND status = ?",
                decided.name(), decidedAt, id, TransferStatus.PENDING.name());
        return updated == 1;
    }

    /**
     * 按发生顺序查询证物全部交接记录。
     */
    public List<TransferRecord> findByEvidenceKey(String evidenceKey) {
        return jdbc.query(
                "SELECT * FROM transfer_record WHERE evidence_key = ? ORDER BY id",
                ROW_MAPPER, evidenceKey);
    }

    private static final class TransferRowMapper implements RowMapper<TransferRecord> {
        @Override
        public TransferRecord mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new TransferRecord(
                    rs.getLong("id"),
                    rs.getString("evidence_key"),
                    rs.getString("from_custodian"),
                    rs.getString("to_custodian"),
                    TransferStatus.valueOf(rs.getString("status")),
                    rs.getString("initiated_by"),
                    rs.getObject("created_at", LocalDateTime.class),
                    rs.getObject("decided_at", LocalDateTime.class));
        }
    }
}

