        String evidenceKey = uniqueKey("EV");
        intake("alice", uniqueKey("CMD"), evidenceKey);
        assertThat(inspect("mallory", evidenceKey, uniqueKey("CMD"), true)
                .getResponse().getStatus()).isEqualTo(409);
    }

    @Test
